    /**
     * Merging local file data from an array of seven diverse extra fields
     * produces the correct total byte length (136 bytes).
     *
     * Fields included: UnicodePathExtraField (twice), X000A_NTFS,
     * UnicodeCommentExtraField, X0015_CertificateIdForFile,
     * ResourceAlignmentExtraField, and UnparseableExtraFieldData.
     */
    @Test(timeout = 4000)
    public void mergeLocalFileDataDataWithSevenFieldsReturnsCorrectLength() throws Throwable {
        ZipExtraField[] fields = new ZipExtraField[7];

        UnicodePathExtraField unicodePath = new UnicodePathExtraField();
        fields[0] = unicodePath;

        X000A_NTFS ntfsField = new X000A_NTFS();
        fields[1] = ntfsField;

        // Reuse the same unicodePath instance at index 2
        fields[2] = unicodePath;

        byte[] eightZeroBytes = new byte[8];
        UnicodeCommentExtraField unicodeComment =
                new UnicodeCommentExtraField("Error parsing extra fields for entry: ", eightZeroBytes);
        fields[3] = unicodeComment;

        X0015_CertificateIdForFile certIdForFile = new X0015_CertificateIdForFile();
        fields[4] = certIdForFile;

        // alignment=4, allowMethodChange=true, methodChange=35
        ResourceAlignmentExtraField alignmentField =
                new ResourceAlignmentExtraField((byte) 4, true, (byte) 35);
        fields[5] = alignmentField;

        UnparseableExtraFieldData unparseable = new UnparseableExtraFieldData();
        fields[6] = unparseable;

        byte[] merged = ExtraFieldUtils.mergeLocalFileDataData(fields);
        assertEquals(136, merged.length);
    }

    /**
     * Merging local file data from an empty array of extra fields
     * produces an empty byte array.
     */
    @Test(timeout = 4000)
    public void mergeLocalFileDataDataWithEmptyArrayReturnsEmptyBytes() throws Throwable {
        ZipExtraField[] noFields = new ZipExtraField[0];
        byte[] merged = ExtraFieldUtils.mergeLocalFileDataData(noFields);
        assertEquals(0, merged.length);
