    /**
     * When the only extra field is an UnparseableExtraFieldData with no data,
     * mergeCentralDirectoryData returns an empty byte array because
     * UnparseableExtraFieldData is treated as a raw data holder (no header prefix).
     */
    @Test(timeout = 4000)
    public void mergeCentralDirectoryDataWithOnlyUnparseableDataReturnsEmptyBytes() throws Throwable {
        UnparseableExtraFieldData unparseable = new UnparseableExtraFieldData();
        ZipExtraField[] fields = new ZipExtraField[]{unparseable};
        byte[] merged = ExtraFieldUtils.mergeCentralDirectoryData(fields);
        assertEquals(0, merged.length);
    }

    /**
     * Merging central directory data from a single UnicodePathExtraField
     * returns the 4-byte header: type id bytes [0x75, 0x70] followed by
     * zero-length indicator [0x00, 0x00].
     */
    @Test(timeout = 4000)
    public void mergeCentralDirectoryDataWithUnicodePathFieldReturnsHeaderAndZeroLength() throws Throwable {
        UnicodePathExtraField unicodePath = new UnicodePathExtraField();
        ZipExtraField[] fields = new ZipExtraField[]{unicodePath};
        byte[] merged = ExtraFieldUtils.mergeCentralDirectoryData(fields);
        // 'u'=0x75, 'p'=0x72 are the UnicodePathExtraField header bytes; length is 0
        assertArrayEquals(new byte[]{(byte) 0x75, (byte) 0x70, (byte) 0x00, (byte) 0x00}, merged);
    }

    /**
     * Parsing a 4-byte buffer where the declared field length (194) exceeds
     * the remaining data (0 bytes after header) triggers READ behavior,
     * capturing the raw bytes as UnparseableExtraFieldData.
     * Re-merging the central directory data reproduces the original 4 bytes.
     */
    @Test(timeout = 4000)
    public void parseCorruptFieldWithReadBehaviorAndMergeCentralDirectoryPreservesBytes() throws Throwable {
        ExtraFieldUtils.UnparseableExtraField readBehavior = ExtraFieldUtils.UnparseableExtraField.READ;
        // Header bytes: 0x00, 0x00. Length bytes: 0xC2 (=-62 unsigned 194), 0x00.
        // Declared length 194 exceeds remaining 0 bytes → unparseable → READ captures all 4 bytes.
        byte[] data = new byte[4];
        data[2] = (byte) (-62);

        ZipExtraField[] parsed = ExtraFieldUtils.parse(data, false, readBehavior);
        byte[] remerged = ExtraFieldUtils.mergeCentralDirectoryData(parsed);

        assertEquals(4, remerged.length);
        assertArrayEquals(new byte[]{(byte) 0x00, (byte) 0x00, (byte) (-62), (byte) 0x00}, remerged);
    }

    /**
     * Parsing a 4-byte all-zero buffer treats it as a valid extra field
     * (header=0x0000, length=0). Re-merging central directory data yields
     * the same 4-byte representation.
     */
    @Test(timeout = 4000)
    public void parseZeroFilledFourByteBufferWithReadBehaviorAndMergeCentralDirectoryReturns4Bytes() throws Throwable {
        ExtraFieldUtils.UnparseableExtraField readBehavior = ExtraFieldUtils.UnparseableExtraField.READ;
        byte[] allZeroData = new byte[4];

        ZipExtraField[] parsed = ExtraFieldUtils.parse(allZeroData, false, readBehavior);
        byte[] remerged = ExtraFieldUtils.mergeCentralDirectoryData(parsed);

        assertEquals(4, remerged.length);
    }

    /**
