    @Test(timeout = 4000)
    public void mergeCentralDirectoryDataWithEmptyArrayReturnsEmptyBytes() throws Throwable {
        ZipExtraField[] noFields = new ZipExtraField[0];
        byte[] merged = ExtraFieldUtils.mergeCentralDirectoryData(noFields);
        assertEquals(0, merged.length);
    }

    /**
     * In STRICT_FOR_KNOW_EXTRA_FIELDS mode, createExtraField for the
     * UnicodePathExtraField header ID returns a UnicodePathExtraField
     * with an initial name CRC32 of zero.
     */
    @Test(timeout = 4000)
    public void createExtraFieldForUnicodePathInStrictModeReturnsFieldWithZeroNameCRC() throws Throwable {
        ZipArchiveEntry.ExtraFieldParsingMode strictMode =
                ZipArchiveEntry.ExtraFieldParsingMode.STRICT_FOR_KNOW_EXTRA_FIELDS;
        ZipShort unicodePathHeaderId = UnicodePathExtraField.UPATH_ID;

        UnicodePathExtraField created =
                (UnicodePathExtraField) strictMode.createExtraField(unicodePathHeaderId);

        assertEquals(0L, created.getNameCRC32());
    }

    /**
     * Parsing an 8-byte buffer whose second field has a truncated payload
     * using ONLY_PARSEABLE_STRICT mode silently drops the truncated field,
     * returning only the one complete parseable field.
     */
    @Test(timeout = 4000)
    public void parseWithOnlyParseableStrictModeAndTruncatedSecondFieldReturnsOneField() throws Throwable {
        ZipArchiveEntry.ExtraFieldParsingMode onlyParseableStrict =
                ZipArchiveEntry.ExtraFieldParsingMode.ONLY_PARSEABLE_STRICT;
        // Bytes [0..3]: first field — header 0x0000, length 0.
        // Bytes [4..7]: second field header 0x0000, byte[7]=-6 makes length=64506 which exceeds remaining data.
        byte[] data = new byte[8];
        data[7] = (byte) (-6);

        ZipExtraField[] parsed = ExtraFieldUtils.parse(data, false, (ExtraFieldParsingBehavior) onlyParseableStrict);

        assertEquals(1, parsed.length);
    }

    /**
     * The default parse() uses THROW behavior; a buffer where the declared
     * length exceeds remaining data triggers a ZipException describing the
     * corrupt extra field.
     */
    @Test(timeout = 4000)
    public void parseDefaultWithTruncatedExtraFieldDataThrowsZipException() throws Throwable {
        // Header 0x0000 with declared length=35 (byte[2]=35), but only 4 bytes after the header.
        byte[] data = new byte[8];
        data[2] = (byte) 35;

        try {
            ExtraFieldUtils.parse(data);
            fail("Expecting exception: ZipException");
        } catch (ZipException e) {
            verifyException("org.apache.commons.compress.archivers.zip.ExtraFieldUtils$UnparseableExtraField", e);
        }
    }

    /**
     * Parsing 13 bytes where the second field has an oversized declared length
     * causes READ behavior to capture the remaining 9 bytes as UnparseableExtraFieldData.
     * The result has 2 fields and merges back to 13 bytes of local file data.
     *
     * Layout: [field1: header=0 len=0 | field2-header: bytes 4-7 with len oversized | raw tail: bytes 8-12]
     */
    @Test(timeout = 4000)
    public void parseTruncatedSecondFieldWithReadBehaviorYieldsTwoFieldsMergingTo13Bytes() throws Throwable {
        ExtraFieldUtils.UnparseableExtraField readBehavior = ExtraFieldUtils.UnparseableExtraField.READ;
        // byte[7]=-8 (unsigned 248) makes second field's declared length 248*256=63488 >> remaining data
        byte[] data = new byte[13];
        data[7] = (byte) (-8);

        ZipExtraField[] parsed = ExtraFieldUtils.parse(data, true, readBehavior);
        byte[] merged = ExtraFieldUtils.mergeLocalFileDataData(parsed);

        assertEquals(2, parsed.length);
        assertEquals(13, merged.length);
    }

